test('paired drafts run two fresh fixed comparisons, bind all four exact references, and publish nothing',async()=>{
 const {original,peer}=await pairedFixture(),{requests}=server([original,peer]),h=harness({outcomeId:peer.outcome.id,outcomeDigest:peer.outcome.digest});await h.until('Exact current outcome');assert(button(h.render(),'Prepare paired review draft').props.disabled);h.field('Confirm local artifact rights',true);await h.flush();let calls=0;globalThis.__comparisonOverride=(raw,actual)=>{calls++;return actual(raw);};h.click('Prepare paired review draft');await h.until('Paired review draft exported');assert.equal(calls,2);assert.equal(h.attempts().length,2);assert(h.attempts().every(item=>item.props['data-status']==='MATCH'));assert.equal(exports.length,1);const draft=JSON.parse(await exports[0].blob.text());assert.equal(draft.kind,'LOCAL_EXPERIMENT_REVIEW_DRAFT');assert.deepEqual(draft.target,{original:{id:original.outcome.id,digest:original.outcome.digest},reproduction:{id:peer.outcome.id,digest:peer.outcome.digest},manifest:{id:original.manifest.id,digest:original.manifest.digest},strategy:{id:original.source.id,digest:original.source.digest}});assert.equal(draft.evidence.original.identity.claimedArtifact,original.artifact.resultDigest);assert.equal(draft.evidence.reproduction.identity.claimedArtifact,peer.artifact.resultDigest);assert.equal(draft.qualification,'NONE');assert.equal(draft.independence,'NOT_ESTABLISHED');assert(!Object.hasOwn(draft,'decision'));assert(!Object.hasOwn(draft,'author'));assert(!Object.hasOwn(draft,'policyAccepted'));assert.equal(draft.ordersEnabled,false);assert(requests.filter(row=>row.path==='/api/experiments?id='+original.outcome.id).length>=4);assert(!requests.some(row=>row.init.method==='POST'||row.path.includes('/me')));assert.equal(urls.size,0);
});

test('paired preparation keeps invented returns as mismatches rather than selecting only successful agreement',async()=>{
 const {original,peer}=await pairedFixture(artifact=>{artifact.metrics.netPnl+=100;artifact.metrics.returnPct+=100;artifact.metrics.finalEquity+=100;}),h=harness({outcomeId:peer.outcome.id});server([original,peer]);await h.until('Exact current outcome');h.field('Confirm local artifact rights',true);await h.flush();h.click('Prepare paired review draft');await h.until('Paired review draft exported');const draft=JSON.parse(await exports[0].blob.text());assert.equal(draft.evidence.original.status,'MATCH');assert.equal(draft.evidence.reproduction.status,'MISMATCH');assert.equal(h.attempts()[1].props['data-status'],'MISMATCH');assert(draft.evidence.reproduction.pairs.some(pair=>pair.differenceCount>0));
});

test('a failed first paired computation cannot suppress the second attempt or create a partial review draft',async()=>{
 const {original,peer}=await pairedFixture();server([original,peer]);const h=harness({outcomeId:peer.outcome.id});await h.until('Exact current outcome');let calls=0;globalThis.__comparisonOverride=(raw,actual)=>{if(++calls===1)throw Error('fixture evaluator failed');return actual(raw);};h.field('Confirm local artifact rights',true);await h.flush();h.click('Prepare paired review draft');await h.until('Both attempts are retained');assert.equal(calls,2);assert.equal(exports.length,0);const history=await session(h);assert.deepEqual(history.attempts.map(row=>row.status),['FAILED','MATCH']);assert.equal(history.attempts[0].report,null);assert(history.attempts[1].report);
});

test('paired cancellation and sign-out interrupt both admitted attempts and prevent late export or further reference reads',async()=>{
 for(const action of ['cancel','logout']){const {original,peer}=await pairedFixture(),{requests}=server([original,peer]),h=harness({outcomeId:peer.outcome.id,signedIn:true});await h.until('Exact current outcome');let release,calls=0;globalThis.__comparisonOverride=(raw,actual)=>{calls++;return new Promise(resolve=>release=async()=>resolve(await actual(raw)));};h.field('Confirm local artifact rights',true);await h.flush();h.click('Prepare paired review draft');await h.until(()=>typeof release==='function');assert.equal(h.attempts().length,2);if(action==='cancel')h.click('Cancel before confirmation');else h.props.signedIn=false;await h.flush();const count=requests.length;await release();await h.flush();assert.equal(requests.length,count);assert.equal(calls,1);assert.equal(exports.length,0);const held=context.refs.find(row=>row.current?.attempts).current;assert(held.attempts.every(row=>row.status==='INTERRUPTED'&&row.report===null));if(action==='logout')assert.equal(held.selection,null);}
});

test('a hidden original after computation clears both paired reports and withholds any downloadable review draft',async()=>{
 const {original,peer}=await pairedFixture(),{records}=server([original,peer]),h=harness({outcomeId:peer.outcome.id});await h.until('Exact current outcome');let calls=0;globalThis.__comparisonOverride=async(raw,actual)=>{const report=await actual(raw);if(++calls===2)records.set(original.outcome.id,hidden(original.outcome));return report;};h.field('Confirm local artifact rights',true);await h.flush();h.click('Prepare paired review draft');await h.until('Paired draft unavailable');assert.equal(exports.length,0);assert.equal(field(h.render(),'Comparison artifact JSON').props.value,'');const held=context.refs.find(row=>row.current?.attempts).current;assert.equal(held.attempts.length,2);assert(held.attempts.every(row=>row.cleared&&row.report===null));assert.equal(button(h.render(),'Export comparison report'),undefined);
});

test('paired preparation reserves two attempt slots and refuses local and continuous sources',async()=>{
 const {original,peer}=await pairedFixture();server([original,peer]);const h=harness();await h.flush();h.field('Comparison artifact JSON','{"invalid":true}');await h.flush();for(let n=0;n<15;n++)await run(h);h.props.outcomeId=peer.outcome.id;await h.until('Exact current outcome');h.field('Confirm local artifact rights',true);await h.flush();assert(button(h.render(),'Prepare paired review draft').props.disabled);assert.equal(h.attempts().length,15);h.click('Use supplied artifact instead');await h.flush();assert.equal(button(h.render(),'Prepare paired review draft'),undefined);const value=await continuousPublic();server([value]);const continuous=harness({outcomeId:value.outcome.id});await continuous.until('Exact current outcome');assert.equal(button(continuous.render(),'Prepare paired review draft'),undefined);
});

test('batch report and complete-history exports refuse newly hidden exact public evidence and scrub held payloads',async()=>{
 for(const control of ['Export comparison report','Export complete comparison session']){const value=await publicFixture(),{records}=server([value]),h=harness({outcomeId:value.outcome.id});await h.until('Exact current outcome');await run(h);records.set(value.manifest.id,hidden(value.manifest));h.click(control);await h.until('Export withheld');assert.equal(exports.length,0);const held=context.refs.find(row=>row.current?.attempts).current;assert.equal(held.selection,null);assert.equal(held.attempts[0].report,null);assert(held.attempts[0].cleared);}
});
